from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class Task:
    title: str
    due: datetime | None = None
    tags: list[str] = field(default_factory=list)
    done: bool = False

    def overdue(self) -> bool:
        if self.due is None or self.done:
            return False
        return self.due < datetime.now()

from datetime import UTC, datetime

import pytest
from tasktrack.models import Task


def test_naive_due_date_in_past_is_overdue():
    assert Task("file taxes", due=datetime(2020, 1, 1)).overdue()


@pytest.mark.xfail(strict=True, reason="ticket 012")
def test_overdue_with_aware_due_date():
    task = Task("pay rent", due=datetime(2020, 1, 1, tzinfo=UTC))
    assert task.overdue()
